// R102-1（本人裁定 2026-09-30「あなた待ちは部屋に重ねず上下に分ける」）: ❗ドックは部屋の窓の下の別の箱（app.css の #room の縦の積み）。
// 窓に重ねていた頃の測り直し（上限・畳み・詰める段＝attnFitPass）は撤去した。入らない分はドックの中をスクロールし、部屋は窓に合わせて ×1 まで縮む（bootpx.js）。
/* R104-1: 窓の外の実寸を引き、×2 と先頭のカード150pxが入る時は部屋を×1へ落とさない。 */
function fitAttnDock(){
  if(TERM)fitTermDrawer();
  var room=document.getElementById("room"),win=document.getElementById("officewin"),wait=document.getElementById("officewait"),dock=document.getElementById("dock"),api=window.__scene3d;
  if(!room||!win)return;
  function reset(){room.style.removeProperty("--win-min");room.removeAttribute("data-room-fit");if(wait)wait.style.removeProperty("--officewait-max");if(dock)dock.style.removeProperty("--dock-max")}
  if(VIEW!=="office"||!api||!api.roomH||!wait||wait.hidden||document.body.classList.contains("term-open")||splitOffice()||WIDE||MINI||innerHeight<=600){reset();return}
  function shown(n){if(!n||n.hidden||n.classList.contains("hidden"))return 0;var c=getComputedStyle(n);if(c.display==="none")return 0;return n.getBoundingClientRect().height+(parseFloat(c.marginTop)||0)+(parseFloat(c.marginBottom)||0)}
  var wrap=document.getElementById("scene3dwrap"),title=win.querySelector(".wtitle"),ws=getComputedStyle(win),rs=getComputedStyle(room);
  var frame=(parseFloat(ws.borderTopWidth)||0)+(parseFloat(ws.borderBottomWidth)||0)+(parseFloat(ws.paddingTop)||0)+(parseFloat(ws.paddingBottom)||0);
  var ds=dock&&getComputedStyle(dock),dockHeight=dock?Math.max(shown(dock),dock.scrollHeight+(parseFloat(ds.borderTopWidth)||0)+(parseFloat(ds.borderBottomWidth)||0)):0;
  var fixed=shown(document.querySelector(".topbar"))+shown(document.getElementById("tabbar"))+shown(document.getElementById("topdock"))+shown(title)+shown(document.getElementById("nextbar"))+dockHeight;
  fixed+=(parseFloat(rs.paddingTop)||0)+(parseFloat(rs.paddingBottom)||0);
  room.querySelectorAll(":scope > .empty").forEach(function(n){fixed+=shown(n)});
  var remaining=innerHeight-fixed,target=api.roomH*2+frame;
  if(!wrap||wrap.clientWidth-6<api.roomW*2||remaining<target+150){reset();return}
  room.style.setProperty("--win-min",Math.ceil(target)+"px");room.setAttribute("data-room-fit","2");
  wait.style.setProperty("--officewait-max",Math.floor(remaining-target)+"px");
  if(dock)dock.style.setProperty("--dock-max",Math.max(44,Math.ceil(dockHeight))+"px");
}
