async function runCryptoSelftest(){
  var hint=document.getElementById('st_cs_hint');
  function say(t){if(hint)hint.textContent=t}
  var st=cryptoStages();
  if(!st.subtle){say(T('✗ この端末は WebCrypto の復号に対応していません','✗ This device has no WebCrypto decrypt'));return}
  if(!st.stream){say(T('✗ この端末は DecompressionStream に対応していません','✗ This device has no DecompressionStream'));return}
  say(T('… 読み込み中','… loading'));
  if(!st.bridge&&!(await ensureDlg())){say(T('✗ 復号モジュールを読み込めませんでした（通信を確認してください）','✗ Could not load the decryption module (check your connection)'));return}
  var k=window.__dlg.kat;
  if(!k){say(T('✗ 検査用データが読み込まれていません','✗ Test vector not loaded'));return}
  say(T('… 実行中','… running'));
  var t0=Date.now();
  try{
    var page=await window.__dlg.openBlob(k.bundle,k.secretHex,k.deviceId,k.targetSession);
    var got=page&&page.messages&&page.messages[0]&&page.messages[0].text;
    if(got!==k.expect){say(T('✗ 復号できたが内容が違う','✗ Decrypted but content differs'));return}
  }catch(e){say('✗ '+T('復号に失敗: ','decrypt failed: ')+(e&&e.message||e));return}
  var ms=Date.now()-t0;
  try{
    await window.__dlg.openBlob(k.bundle,k.secretHex,'dev-other-0001',k.targetSession);
    say(T('✗ 別端末のふりでも開けてしまう（認証が効いていない）','✗ Opened with the wrong device id (authentication is not working)'));return;
  }catch(e){}
  say('✓ '+T('この端末で会話を復号できます（'+ms+'ms・改竄も拒否）','This device can decrypt conversations ('+ms+'ms, tampering rejected)'));
  playSE('select');
}

